 fn page_index(
     observation: &PageObservation, collection: EvidenceDigest, event: &str, page: u32, checkpoint: EvidenceDigest,
 ) -> anyhow::Result<RankingPageIndex> {
     let individual = observation.grade_11_candidates_list.iter().enumerate().map(|(index, candidate)| {
         Ok(RankingCandidateEntry { name: candidate.name.clone(), athlete_id: candidate.athlete_id,
             kind: RankingCandidateKind::Individual, record_index: u32::try_from(index)?, result_id: candidate.id_result })
     });
     let relay = observation.verified_relay_members.iter().enumerate().map(|(index, member)| {
         Ok(RankingCandidateEntry { name: member.name.clone(), athlete_id: member.athlete_id,
             kind: RankingCandidateKind::RelayMember, record_index: u32::try_from(index)?, result_id: member.id_result })
     });
     Ok(RankingPageIndex {
         collection, event_short: event.to_owned(), page, checkpoint,
         candidates: individual.chain(relay).collect::<anyhow::Result<Vec<_>>>()?,
         rows: observation.source_rows.iter().map(|row| RankingSourceRow {
             result_id: row.result_id, row_number: row.row_number,
         }).collect(),
         rosters: observation.source_rows.iter().filter_map(|row| row.roster_present.map(|present| {
             RankingRosterObservation { result_id: row.result_id, present }
         })).collect(),
     })
 }

-pub(super) fn seal(store: &ArtifactStore, state: &CollectionState, collection: &EvidenceDigest) -> anyhow::Result<EvidenceDigest> {
+pub(super) fn seal(store: &ArtifactStore, state: &CollectionState, collection: &EvidenceDigest) -> anyhow::Result<EvidenceDigest> {
     if state.events.is_empty() || state.events.iter().any(|event| !event.terminal || event.head_checkpoint.is_none()) {
         bail!("cannot seal an incomplete ranking collection");
     }
     let snapshot = CollectionFinalSnapshot {
-        collection: collection.clone(), source_snapshot: state.source_snapshot.clone(), scope: state.scope.clone(),
+        collection: collection.clone(), source_snapshot: state.source_snapshot.clone(), scope: state.scope.clone(),
