         catalog_ref: state.catalog_ref.clone(), plan_ref: state.plan_ref.clone(),
         event_heads: state.events.iter().map(|event| EventHeadRef {
             event_short: event.event_short.clone(), head_checkpoint: event.head_checkpoint.clone(),
             page_count: event.page_count, terminal: event.terminal,
         }).collect(),
         coverage: CoverageSummary { total_requested: state.events.len() as u64,
             completed: state.events.len() as u64, absent_families: state.absent_families.clone() },
         unique_athletes: store.ranking_collection_stats(collection)?.unique_athletes,
     };
     let digest = put(store, &snapshot)?;
     store.seal_rankings(collection, &digest)?;
     Ok(digest)
 }
